<?php
$page_title='รายละเอียดคำสั่งซื้อ'; require_once __DIR__.'/includes/auth_check.php'; requireLogin(); require_once __DIR__.'/config/database.php';
$db=(new Database())->getConnection();$id=(int)($_GET['id']??0);$order=null;$items=[];
if($db&&$id){$s=$db->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$id,(int)$_SESSION['user_id']]);$order=$s->fetch();if($order){$s=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();}}
