?><div class="container" style="max-width:850px;margin-top:36px;margin-bottom:60px"><a href="<?php echo BASE_URL; ?>my-orders.php">← กลับไปประวัติคำสั่งซื้อ</a><section style="background:#fff;padding:30px;border-radius:var(--radius-md);margin-top:18px"><h1>คำสั่งซื้อ <?php echo e($order['order_no']); ?></h1><p>วันที่ <?php echo date('d/m/Y H:i',strtotime($order['created_at'])); ?> · สถานะ <?php echo e($order['order_status']); ?></p><hr style="margin:20px 0;border:0;border-top:1px solid var(--border-color)"><?php foreach($items as $item): ?><div style="display:flex;justify-content:space-between;padding:8px 0"><span><?php echo e($item['product_name']); ?> × <?php echo (int)$item['quantity']; ?></span><strong><?php echo formatCurrency($item['subtotal']); ?></strong></div><?php endforeach; ?><hr style="margin:16px 0"><div style="display:flex;justify-content:space-between;font-size:1.2rem"><strong>ยอดรวม</strong><strong><?php echo formatCurrency($order['total_amount']); ?></strong></div><h3 style="margin-top:24px">ข้อมูลจัดส่ง</h3><p><?php echo e($order['shipping_name']); ?> · <?php echo e($order['shipping_phone']); ?><br><?php echo nl2br(e($order['shipping_address'])); ?></p><?php if($order['payment_method']==='promptpay'&&$order['payment_status']==='pending'): ?><a class="btn btn-primary" style="margin-top:20px" href="<?php echo BASE_URL; ?>order-success.php?order_id=<?php echo $id; ?>">ไปหน้าชำระเงิน</a><?php endif; ?></section></div><?php require_once __DIR__.'/includes/footer.php'; ?>
